from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

old="function openActions(){show('actions');$('actDate').value=app.calendarDate||app.date;renderActions()}"
new="async function openActions(){show('actions');$('actDate').value=app.calendarDate||app.date;shortagesData=await api('shortages');renderActions()}"
assert old in s, 'openActions function not found'
s=s.replace(old,new,1)

pattern=r"function renderActions\(\)\{.*?\}function actionById"
replacement=r'''function renderActions(){let t=$('filterType').value,s=$('filterStatus').value,a=app.actions.filter(x=>{if(t&&x.action_type!==t)return false;let ds=actionDisplayStatus(x);if(!s)return true;if(s==='تم التصعيد')return ds==='تم التصعيد — قيد المتابعة';return ds===s});$('actionList').innerHTML=a.map(x=>{let ds=actionDisplayStatus(x),closed=x.action_status==='مغلق',shortage=shortagesData.find(q=>q.action_id===x.id),controls='';if(closed){controls=`<div class="notice ok"><b>تم الإغلاق</b>${x.resolution_result?`<div style="margin-top:6px">نتيجة المعالجة: ${esc(x.resolution_result)}</div>`:''}${shortage?.supplied_date?`<div style="margin-top:6px">تاريخ التغذية: ${shortage.supplied_date}</div>`:''}</div>`}else if(shortage){controls=`<div class="notice"><b>هل تمت التغذية؟</b><div class="actions" style="justify-content:flex-start"><button class="mini" style="color:#166534;border-color:#86c99a;font-weight:700" onclick="shortageSupplyYes('${x.id}')">نعم</button><button class="mini" style="color:#8a1c1c;border-color:#efb4b4;font-weight:700" onclick="shortageSupplyNo('${x.id}')">لا</button></div><div class="mut" style="margin-top:8px">آخر متابعة: ${x.last_update||x.request_date}</div></div><div class="actions" style="justify-content:flex-start"><button class="mini" style="color:#725700;border-color:#d7bb74;font-weight:700" onclick="escalateAction('${x.id}')">بحاجة إلى تصعيد</button></div>`}else{controls=`<div class="actions" style="justify-content:flex-start"><button class="mini" style="color:#166534;border-color:#86c99a;font-weight:700" onclick="closeAction('${x.id}')">تم الإغلاق</button><button class="mini" style="color:#725700;border-color:#d7bb74;font-weight:700" onclick="escalateAction('${x.id}')">بحاجة إلى تصعيد</button></div>`}return `<div class="task"><b>${esc(x.action_type)} — ${esc(x.subject)}</b><div class="mut" style="margin-top:6px">تاريخ التسجيل: ${x.request_date} | الحالة: <b>${esc(ds)}</b></div><p><b>وصف المطلوب:</b> ${esc(x.description||'')}</p>${x.raised_to&&!closed?`<div class="notice">آخر جهة تم التصعيد لها: <b>${esc(x.raised_to)}</b></div>`:''}${controls}</div>`}).join('')||'<p class="mut">لا توجد إجراءات.</p>'}async function shortageSupplyYes(id){try{let x=actionById(id),shortage=shortagesData.find(q=>q.action_id===id);if(!x||!shortage)throw Error('طلب النقص المرتبط غير موجود');if(x.action_status==='مغلق')throw Error('الطلب مغلق');if(!confirm('تأكيد أن التغذية وصلت؟ سيتم إغلاق المتابعة وتحديث سجل النقص.'))return;await api('action-save',{method:'POST',body:actionUpdateBody(x,{action_status:'مغلق',resolution_result:'تمت التغذية',last_update:app.calendarDate||app.date})});await refresh();shortagesData=await api('shortages');show('actions');renderActions();alert('تم تسجيل وصول التغذية وإغلاق المتابعة')}catch(e){alert(e.message)}}async function shortageSupplyNo(id){try{let x=actionById(id),shortage=shortagesData.find(q=>q.action_id===id);if(!x||!shortage)throw Error('طلب النقص المرتبط غير موجود');if(x.action_status==='مغلق')throw Error('الطلب مغلق');await api('action-save',{method:'POST',body:actionUpdateBody(x,{action_status:x.action_status||'قيد المتابعة',last_update:app.calendarDate||app.date})});await refresh();shortagesData=await api('shortages');show('actions');renderActions();alert('تم تحديث المتابعة — التغذية لم تصل بعد')}catch(e){alert(e.message)}}function actionById'''
s,n=re.subn(pattern,replacement,s,count=1,flags=re.S)
assert n==1,'renderActions block not found'

pattern2=r"function renderShortages\(\)\{.*?\}async function orderShortage"
replacement2=r'''function renderShortages(){let secs=app.sections.filter(s=>s.display_order<=10),rows=shortageSectionFilter?shortagesData.filter(x=>x.section_id===shortageSectionFilter):shortagesData;$('shortFilters').innerHTML=`<button class="mini" style="${!shortageSectionFilter?'background:#17365d;color:#fff;':''}" onclick="setShortageFilter('')">الكل</button>`+secs.map(s=>`<button class="mini" style="${shortageSectionFilter===s.id?'background:#17365d;color:#fff;':''}" onclick="setShortageFilter('${s.id}')">${esc(s.name)}</button>`).join('');$('shortList').innerHTML='<div class="scroll"><table><thead><tr><th>القسم</th><th>المقاس</th><th>الموجود</th><th>المطلوب</th><th>الفرص</th><th>أول رصد</th><th>تاريخ الطلب</th><th>تاريخ التغذية</th><th>الحالة</th><th></th></tr></thead><tbody>'+rows.map(s=>`<tr><td>${esc(s.sections?.name)}</td><td>${esc(s.size)}</td><td>${s.current_qty}</td><td>${s.requested_qty}</td><td>${s.lost_opportunities}</td><td>${s.first_detected_date}</td><td>${s.ordered_date||'—'}</td><td>${s.supplied_date||'—'}</td><td>${s.shortage_status}</td><td>${s.shortage_status==='مفتوح'?`<button class="mini" style="color:#17365d;border-color:#9db0c5;font-weight:700" onclick="orderShortage('${s.id}')">تم الطلب</button>`:s.shortage_status==='تم الطلب'?'<span class="chip">تم تحويله للمتابعة</span>':s.shortage_status==='تمت التغذية'?'<span class="chip">تمت التغذية</span>':''}</td></tr>`).join('')+'</tbody></table></div>'}async function orderShortage'''
s,n=re.subn(pattern2,replacement2,s,count=1,flags=re.S)
assert n==1,'renderShortages block not found'

# Force Pages to publish this exact UI revision.
marker='<!-- pages-publish: shortage-supply-followup-2026-08-24 -->'
s=re.sub(r'<!-- pages-publish: [^>]+ -->',marker,s,count=1)
if marker not in s:
    s=s.replace('<title>ركيزة V1</title>','<title>ركيزة V1</title>'+marker,1)

p.write_text(s,encoding='utf-8')
